"""Generate the default 50-station Compose fleet with stable identities."""
from pathlib import Path


def generate():
    lines = [
        "# Generated by generate_compose.py; do not scale a single station service.",
        "x-station: &station", "  build: .", "  image: hcm-station-simulator:local",
        "  restart: unless-stopped", "  volumes:", "    - simulator-state:/state",
        "  environment: &station-env", "    PYTHONUNBUFFERED: '1'",
        "    STATE_DIR: /state", "    THINGSBOARD_HOST: ${THINGSBOARD_HOST:-10.0.1.200}",
        "    PORT: ${PORT:-1883}", "    PROVISION_KEY: ${PROVISION_KEY:-}",
        "    PROVISION_SECRET: ${PROVISION_SECRET:-}", "services:",
    ]
    for index in range(50):
        lines += [f"  station-{index + 1:03d}:", "    <<: *station", "    environment:",
                  "      <<: *station-env", f"      NODE_INDEX: '{index}'",
                  f"      DEVICE_NAME: VN-HCM-{index + 1:03d}"]
    return "\n".join(lines + ["volumes:", "  simulator-state:", ""])


if __name__ == "__main__":
    for name in ("docker-compose.yml", "compose.fleet.yml"):
        Path(__file__).with_name(name).write_text(generate(), encoding="utf-8")
    print("Generated default fleet: 50 unique stations, persistent credentials")
